import nextWorker from '../.open-next/worker.js';

/** This preview serves the public presentation only. It never starts AI jobs,
 * signs users in, or forwards an existing production session to an unported DB. */
export default {
  async fetch(request: Request, env: Cloudflare.Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);
    if (url.pathname === '/api/migration-readiness') {
      return Response.json({
        status: 'preparation-only', database: 'not-connected',
        aiExecution: 'disabled', productionReady: false,
      }, { status: 503, headers: { 'Cache-Control': 'no-store' } });
    }
    const publicPage = ['/', '/termeni', '/confidentialitate'].includes(url.pathname);
    const staticAsset = url.pathname.startsWith('/_next/') || /\.(?:svg|png|webp|jpg|jpeg|ico|woff2?)$/.test(url.pathname);
    if (!['GET', 'HEAD'].includes(request.method) || url.pathname.startsWith('/api/') || !(publicPage || staticAsset) ||
        (publicPage && [...url.searchParams.keys()].length > 0)) {
      return Response.json({ error: 'Migrarea este în pregătire. Autentificarea și analizele nu sunt active în această previzualizare.' },
        { status: 503, headers: { 'Cache-Control': 'no-store', 'Retry-After': '3600' } });
    }
    const anonymous = new Request(request);
    anonymous.headers.delete('cookie');
    anonymous.headers.delete('authorization');
    const response = await nextWorker.fetch(anonymous, env, ctx);
    if (!publicPage || !response.headers.get('content-type')?.includes('text/html')) return response;
    const preview = new Response(response.body, response);
    preview.headers.set('X-Robots-Tag', 'noindex, nofollow');
    preview.headers.set('Cache-Control', 'no-store');
    return preview;
  },
};
